describe("object types, interfaces, aliases, mapped types", () => {
  test.each([
    ["interface as {}", ""], // ifaceName; bun now: Expected identifier but found end of file; expected: equivalent "interface A {}"
    ["export interface as {}", ""], // ifaceName; bun now: Expected identifier but found end of file; expected: equivalent "export interface A {}"
    ["interface satisfies {}", ""], // ifaceName; bun now: Expected identifier but found end of file; expected: equivalent "interface A {}"
    ["export interface satisfies {}", ""], // ifaceName; bun now: Expected identifier but found end of file; expected: equivalent "export interface A {}"
    ["type as = 1", ""], // aliasName; bun now: Unexpected =; expected: equivalent "type A = 1"
    ["declare type as = 1", ""], // aliasName; bun now: Unexpected =; expected: equivalent "declare type A = 1"
    ["type satisfies = 1", ""], // aliasName; bun now: Unexpected =; expected: equivalent "type A = 1"
    ["declare type satisfies = 1", ""], // aliasName; bun now: Unexpected =; expected: equivalent "declare type A = 1"
  ])("ts %j", (source, expected) => {
    expect(transpilers.ts.transformSync(source)).toBe(expected);
  });
});

