describe("assertions, instantiation expressions, generic arrows", () => {
  // A reserved word stands where a type name is expected. tsc parses a type reference and reports TS2304.
  test.each([
    ["const v = x as if;", "const v = x;\n"], // as; bun now: Unexpected if; expected: tsc
    ["const v = x as var;", "const v = x;\n"], // as; bun now: Unexpected var; expected: tsc
    ["const v = <in>x;", "const v = x;\n"], // cast; bun now: The modifier "in" is not valid here; expected: tsc
    ["const v = <in>(x);", "const v = x;\n"], // cast; bun now: The modifier "in" is not valid here; expected: tsc
    ["const v = <if>x;", "const v = x;\n"], // cast; bun now: Unexpected if; expected: tsc
    ["const v = (): if => x;", "const v = () => x;\n"], // arrow; bun now: Expected "=>" but found ":"; expected: tsc
  ])("ts reserved word %j", (source, expected) => {
    expect(transpilers.ts.transformSync(source)).toBe(expected);
  });
  test.each([
    ["const v = x as T <= y;", "const v = x <= y;\n"], // as; bun now: Unexpected =; expected: tsc
    ["x as T <= y;", "x <= y;\n"], // as; bun now: Unexpected =; expected: tsc
    ["const v = <out>x;", "const v = x;\n"], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["<out>x;", "x;\n"], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["const v = <out>(x);", "const v = x;\n"], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["<out>(x);", "x;\n"], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["const v = <out>(x) => x;", "const v = (x) => x;\n"], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["<out>(x) => x;", ""], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["const v = <out, T>(x) => x;", "const v = (x) => x;\n"], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["<out, T>(x) => x;", ""], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["const v = <out = A>(x) => x;", "const v = (x) => x;\n"], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["<out = A>(x) => x;", ""], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["const v = y ? a ? ((b)) : c => d : z;", "const v = y ? a ? b : (c) => d : z;\n"], // arrow; bun now: Expected ":" but found ";"; expected: tsc, printed by the js loader
  ])("ts %j", (source, expected) => {
    expect(transpilers.ts.transformSync(source)).toBe(expected);
  });
  // A reserved word stands where a type name is expected. tsc parses a type reference and reports TS2304.
  test.each([
    ["x as if;", "x;\n"], // as; bun now: Unexpected if; expected: tsc
    ["x as var;", "x;\n"], // as; bun now: Unexpected var; expected: tsc
    ["(): if => x;", ""], // arrow; bun now: Expected "=>" but found ":"; expected: tsc
  ])("tsx reserved word %j", (source, expected) => {
    expect(transpilers.tsx.transformSync(source)).toBe(expected);
  });
  test.each([
    ["f(x as T <= y);", "f(x <= y);\n"], // as; bun now: Unexpected =; expected: tsc
    ["const v = [x as T <= y];", "const v = [x <= y];\n"], // as; bun now: Unexpected =; expected: tsc
    ["f(<out, T>(x) => x);", "f((x) => x);\n"], // cast; bun now: The modifier "out" is not valid here; expected: tsc
    ["f(<out = A>(x) => x);", "f((x) => x);\n"], // cast; bun now: The modifier "out" is not valid here; expected: tsc
  ])("tsx %j", (source, expected) => {
    expect(transpilers.tsx.transformSync(source)).toBe(expected);
  });
});

