// The text of the second argument of every call ("design:type" | "design:paramtypes" | "design:returntype", value).
function metadata(js: string) {
  const found: Record<string, string> = {};
  const call = /\(\s*"design:(type|paramtypes|returntype)"\s*,/g;
  for (let m = call.exec(js); m; m = call.exec(js)) {
    let depth = 0;
    let end = call.lastIndex;
    for (; end < js.length; end++) {
      const c = js[end];
      if (c === "(" || c === "[") depth++;
      else if (c === ")" || c === "]") {
        if (depth === 0) break;
        depth--;
      }
    }
    found[m[1]] = js.slice(call.lastIndex, end).replace(/\s+/g, " ").trim().replace(/^\[ /, "[").replace(/ \]$/, "]");
  }
  return found;
}

